{
  "name": "@nemowang2003/opencode-goal-plugin",
  "version": "0.1.25",
  "description": "OpenCode goal plugin that adds Codex-style long-running goal mode, /goal commands, persistence, and TUI status for AI coding agents.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode goal plugin",
    "opencode goal mode",
    "opencode ai",
    "goal",
    "goal-mode",
    "slash-command",
    "coding-agent",
    "ai-agent",
    "developer-tools",
    "agent",
    "tui"
  ],
  "homepage": "https://github.com/nemowang2003/opencode-goal-plugin#readme",
  "bugs": {
    "url": "https://github.com/nemowang2003/opencode-goal-plugin/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nemowang2003/opencode-goal-plugin.git"
  },
  "license": "MIT",
  "author": "nemowang2003",
  "type": "module",
  "exports": {
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./src/tui.tsx"
    }
  },
  "files": [
    "dist",
    "src/tui.tsx",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build": "bun run clean && bun build ./src/server.ts --outdir ./dist --target bun --external @opencode-ai/plugin --external effect --external zod",
    "ci:version": "bun scripts/resolve-ci-version.ts",
    "lint": "eslint .",
    "pack:dry-run": "npm pack --dry-run",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run test && bun run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.1",
    "@opentui/solid": "^0.4.0",
    "effect": "^3.21.2",
    "solid-js": "1.9.12",
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "@opentui/core": "^0.4.0",
    "@types/bun": "^1.3.13",
    "eslint": "^10.3.0",
    "typescript": "^6.0.3",
    "typescript-eslint": "^8.59.2"
  },
  "engines": {
    "opencode": ">=1.17.1"
  },
  "publishConfig": {
    "access": "public"
  }
}
